     1|/**
     2| * ShimmerIndicator — Drop-in replacement for ActivityIndicator.
     3| *
     4| * Instead of a spinning circle (which signals "waiting"), this renders
     5| * a subtle pulsing dot that matches Instagram's content-loading aesthetic.
     6| * The user perceives content is arriving, not that the app is stuck.
     7| *
     8| * Use this anywhere you would use ActivityIndicator. Same props API.
     9| */
    10|import React, { useEffect, useRef } from 'react';
    11|import { View, Animated, StyleSheet, Platform } from 'react-native';
    12|import Colors from '@/constants/colors';
    13|
    14|type ShimmerIndicatorProps = {
    15|  size?: 'small' | 'large' | number;
    16|  color?: string;
    17|  style?: any;
    18|  animating?: boolean;
    19|};
    20|
    21|const SIZE_MAP = {
    22|  small: 20,
    23|  large: 36};
    24|
    25|export function ShimmerIndicator({
    26|  size = 'small',
    27|  color,
    28|  style,
    29|  animating = true}: ShimmerIndicatorProps) {
    30|  const scale = useRef(new Animated.Value(0.85)).current;
    31|  const opacity = useRef(new Animated.Value(0.4)).current;
    32|  const dotSize = typeof size === 'number' ? size : SIZE_MAP[size];
    33|
    34|  useEffect(() => {
    35|    if (!animating) return;
    36|    const anim = Animated.loop(
    37|      Animated.sequence([
    38|        Animated.parallel([
    39|          Animated.timing(scale, {
    40|            toValue: 1.1,
    41|            duration: 600,
    42|            useNativeDriver: true}),
    43|          Animated.timing(opacity, {
    44|            toValue: 0.9,
    45|            duration: 600,
    46|            useNativeDriver: true}),
    47|        ]),
    48|        Animated.parallel([
    49|          Animated.timing(scale, {
    50|            toValue: 0.85,
    51|            duration: 600,
    52|            useNativeDriver: true}),
    53|          Animated.timing(opacity, {
    54|            toValue: 0.4,
    55|            duration: 600,
    56|            useNativeDriver: true}),
    57|        ]),
    58|      ])
    59|    );
    60|    anim.start();
    61|    return () => anim.stop();
    62|  }, [animating, scale, opacity]);
    63|
    64|  const dotColor = color ?? Colors.primary;
    65|
    66|  return (
    67|    <View style={[styles.container, { width: dotSize, height: dotSize }, style]}>
    68|      <Animated.View
    69|        style={[
    70|          styles.dot,
    71|          {
    72|            width: dotSize,
    73|            height: dotSize,
    74|            borderRadius: dotSize / 2,
    75|            backgroundColor: dotColor,
    76|            transform: [{ scale }],
    77|            opacity},
    78|        ]}
    79|      />
    80|    </View>
    81|  );
    82|}
