     1|/**
     2| * ViewportTracker — reusable FlatList viewport integration for the media lifecycle.
     3| *
     4| * Combines onViewableItemsChanged, scroll-velocity detection, and scope focus
     5| * lifecycle into a single helper. The child FlatList is cloned and given the
     6| * required callbacks, while the parent retains full control over its data.
     7| */
     8|import React, { useCallback, useRef } from 'react';
     9|import { FlatList, type FlatListProps, type NativeScrollEvent, type NativeSyntheticEvent, type ViewToken } from 'react-native';
