    12|import { mediaLifecycleController } from '../controller';
    13|import { useMediaLifecycleViewport } from '../hooks';
    14|import type { MediaScope, MediaType } from '../types';
    15|
    16|interface ViewportTrackerProps<ItemT> extends Omit<FlatListProps<ItemT>, 'onViewableItemsChanged' | 'viewabilityConfig'> {
    17|  scope: MediaScope;
    18|  module: string;
    19|  flatListRef?: React.Ref<FlatList<ItemT>>;
