    22|  extractMediaType?: (item: ItemT, index: number) => MediaType;
    23|  extractSourceUrl?: (item: ItemT, index: number) => string | null;
    24|  extractThumbnailUrl?: (item: ItemT, index: number) => string | null;
    25|  extractFullResolutionUrl?: (item: ItemT, index: number) => string | null;
    26|  extractContainerId?: (item: ItemT, index: number) => string | null;
    27|  /** Viewability percent threshold for the primary item. */
    28|  viewabilityPercentThreshold?: number;
    29|  /** Existing onScroll callback to preserve. */
    30|  onScrollOriginal?: (event: NativeSyntheticEvent<NativeScrollEvent>) => void;
    31|  /** Existing onViewableItemsChanged callback to preserve. */
    32|  onViewableItemsChanged?: (info: { viewableItems: ViewToken[]; changed: ViewToken[] }) => void;
    33|}
    34|
    35|export const ViewportTracker = React.memo(function ViewportTracker<ItemT>(props: ViewportTrackerProps<ItemT>) {
