    38|    module,
    39|    flatListRef,
    40|    extractMediaId,
    41|    extractMediaType,
    42|    extractSourceUrl,
    43|    extractThumbnailUrl,
    44|    extractFullResolutionUrl,
    45|    extractContainerId,
    46|    viewabilityPercentThreshold = 70,
    47|    onScrollOriginal,
    48|    onViewableItemsChanged: originalOnViewableItemsChanged,
    49|    ...flatListProps
    50|  } = props;
    51|
    52|  const { registerAll, handleViewableItemsChanged, handleScroll } = useMediaLifecycleViewport({
    53|    scope,
    54|    module,
    55|    keyExtractor: (item, index) => extractMediaId?.(item as ItemT, index) ?? `${scope}:${index}`,
    56|    getMediaType: (item, index) => extractMediaType?.(item as ItemT, index) ?? 'image',
    57|    getSourceUrl: (item, index) => extractSourceUrl?.(item as ItemT, index) ?? null,
    58|    getThumbnailUrl: (item, index) => extractThumbnailUrl?.(item as ItemT, index) ?? null,
    59|    getFullResolutionUrl: (item, index) => extractFullResolutionUrl?.(item as ItemT, index) ?? null,
    60|    getContainerId: (item, index) => extractContainerId?.(item as ItemT, index) ?? null,
    61|  });
    62|
    63|  const itemsRef = useRef<ItemT[] | null | undefined>(flatListProps.data as ItemT[] | null | undefined);
    64|  itemsRef.current = flatListProps.data as ItemT[] | null | undefined;
    65|
    66|  const registerOnDataChange = useCallback(() => {
    67|    registerAll(itemsRef.current as unknown[]);
    68|  }, [registerAll]);
    69|
    70|  // Register items whenever the data changes.
    71|  React.useEffect(() => {
    72|    registerOnDataChange();
    73|  }, [registerOnDataChange]);
    74|
    75|  useFocusEffect(
    76|    React.useCallback(() => {
    77|      mediaLifecycleController.resumeScope(scope);
    78|      return () => {
    79|        mediaLifecycleController.suspendScope(scope);
    80|      };
    81|    }, [scope]),
    82|  );
    83|
    84|  const isAppForeground = useAppForeground();
    85|  React.useEffect(() => {
    86|    if (!isAppForeground) {
    87|      mediaLifecycleController.releaseScope(scope);
    88|    } else {
    89|      mediaLifecycleController.resumeScope(scope);
    90|    }
    91|  }, [isAppForeground, scope]);
    92|
    93|  const combinedOnViewableItemsChanged = useCallback(
    94|    (info: { viewableItems: ViewToken[]; changed: ViewToken[] }) => {
    95|      handleViewableItemsChanged({ viewableItems: info.viewableItems });
    96|      originalOnViewableItemsChanged?.(info);
    97|    },
    98|    [handleViewableItemsChanged, originalOnViewableItemsChanged],
    99|  );
   100|
   101|  const combinedOnScroll = useCallback(
   102|    (event: NativeSyntheticEvent<NativeScrollEvent>) => {
   103|      handleScroll(event);
   104|      onScrollOriginal?.(event);
   105|    },
   106|    [handleScroll, onScrollOriginal],
   107|  );
   108|
   109|  const viewabilityConfig = React.useRef({ itemVisiblePercentThreshold: viewabilityPercentThreshold }).current;
   110|
   111|  return (
   112|    <FlatList
   113|      ref={flatListRef}
   114|      {...flatListProps}
   115|      onViewableItemsChanged={combinedOnViewableItemsChanged}
   116|      viewabilityConfig={viewabilityConfig}
   117|      onScroll={combinedOnScroll}
   118|    />
   119|  );
   120|}) as <ItemT>(props: ViewportTrackerProps<ItemT>) => React.ReactElement;

