    36|function applyDeltaToQueryCache(
    37|  queryClient: QueryClient,
    38|  queryKeyPrefix: string[],
    39|  event: RealtimeEvent,
    40|  record: Record<string, unknown> | undefined,
    41|): void {
    42|  if (!record) return;
    43|  const recordId = String(record.id ?? '');
    44|  if (!recordId) return;
    45|
    46|  // Find all cached pages for this query key prefix
    47|  queryClient.setQueriesData<{ items: unknown[]; hasMore: boolean }>(
    48|    { queryKey: queryKeyPrefix },
    49|    (cached) => {
    50|      if (!cached || !Array.isArray(cached.items)) return cached;
    51|
    52|      const items = cached.items as Array<Record<string, unknown> & { id?: string }>;
    53|      const existingIndex = items.findIndex((item) => String(item?.id) === recordId);
    54|
    55|      switch (event) {
    56|        case 'INSERT': {
    57|          if (existingIndex >= 0) {
    58|            // Already exists — update in place (avoid duplicate)
    59|            const updated = [...items];
    60|            updated[existingIndex] = record as Record<string, unknown> & { id?: string };
    61|            return { ...cached, items: updated };
    62|          }
    63|          // Insert at the beginning (newest first)
    64|          return { ...cached, items: [record as Record<string, unknown> & { id?: string }, ...items] };
    65|        }
    66|        case 'UPDATE': {
    67|          if (existingIndex >= 0) {
    68|            const updated = [...items];
    69|            updated[existingIndex] = record as Record<string, unknown> & { id?: string };
    70|            return { ...cached, items: updated };
    71|          }
    72|          // Not in current page — ignore (will appear on next page fetch)
    73|          return cached;
    74|        }
    75|        case 'DELETE': {
    76|          if (existingIndex >= 0) {
    77|            return { ...cached, items: items.filter((_, i) => i !== existingIndex) };
    78|          }
    79|          return cached;
    80|        }
    81|        default:
    82|          return cached;
    83|      }
    84|    },
    85|  );
